INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at)
VALUES ('无问芯穹', NULL, 'ai', 'maas', false, 'C 轮', NULL, 50, NULL, '2026-10', '{"name":"无问芯穹","code":"—","industry":"ai","seg":"maas","listed":false,"desc":"清华系 AI 原生基础设施（AI Infra）独角兽，2023 年 5 月由清华大学电子工程系长聘教授汪玉联合学生夏立雪（联合创始人兼 CEO）、戴国浩等人创立，为清华大学与上海交通大学科技成果转化企业。公司不生产芯片、也不持有实体数据中心，而是将不同厂商、代际、地域的算力统一调度为可调用的 Token，提出 Agentic Infra 范式（底座本身内置智能体，自主完成算力优化），并以「前店后厂一中心」战略落地。","valuation":50,"round":"C 轮","lastFunding":"2026-10","latestFunding":"2026-10 · C 轮 23 亿元（累计 43 亿元，单轮及累计均创国内 AI Infra 赛道纪录）；投资方涵盖国资、产业与财务三类资本。市场普遍判断本轮为 Pre-IPO 轮，公司被曝已以保密形式向港交所递交 IPO 申请，最早或于 2027 年上半年挂牌。","execChanges":[],"latestTech":"Agentic Infra 自主式基础设施平台（算力集散中心）目前纳管算力规模 37,000P，原生支持 16 种主流 AI 芯片，可纳管十万卡级集群，支持大模型训练、推理、强化学习混合负载；新芯片适配周期压缩至天级，国产芯片适配成本下降 70% 以上，混合异构训练场景算力利用率最高可达 97.6%。Token 工厂依托基础设施智能体蜂群（平台管家、智算运维、算子生成 KernelMind），KernelMind 可自主完成算子需求分析、内核生成、沙箱验证与迭代沉淀，在 AMD 芯片上实现模型端到端性能提升 39%；过去一年推动推理成本实现 10 倍下降，智能体运维体系将运维人效提升 5 倍、故障处理效率提升 6 倍。","tech":[{"date":"2026-10","title":"发布 Agentic Infra 与「前店后厂一中心」体系","kind":"架构","desc":"提出 AI 生产力 = 智能资源规模 × Token 生产效率 × Token 价值转化效率；算力集散中心纳管 37,000P 算力、覆盖 16 种主流芯片。"},{"date":"2026-07","title":"WAIC 发布跨集群异构 PDD 架构","kind":"技术","desc":"首 Token 延迟降低 51.5%，单 Token 成本降低 37.5%。"}],"funding":[{"date":"2026-10","round":"C轮","amount":"23亿元","inv":"国资：杭州高新金投、社保中关村基金（君联资本管理）、珠海科技产业集团、厦门国兴投资、徐汇资本、孚腾资本、中保投资、国开科创等；产业：Dabanc Holding、联想、九坤创投、同歌创投、腾讯、百度等；财务：红杉中国、洪泰基金、惠远资本、启明创投、达晨财智、顺为资本、砺思资本等"},{"date":"2026-05","round":"融资","amount":"超7亿元","inv":"杭州高新金投集团、惠远资本联合领投，国兴资本、秦淮数据等跟投，君联资本、上海国投孚腾、元智未来追加"},{"date":"2025-11","round":"A+轮","amount":"近5亿元","inv":"珠海科技产业集团、孚腾资本领投，惠远资本、尚颀资本、弘晖基金跟投，洪泰基金、达晨财智、联想创投、君联资本等老股东追加"},{"date":"2025-05","round":"战略融资","amount":"超7亿元","inv":"杭州高新金投集团、惠远资本联合领投，国兴资本、秦淮数据、广发乾和等跟投，君联资本、上海国投孚腾、元智未来等老股东追加"},{"date":"2025-03","round":"A+ 轮","amount":"数亿元","inv":"社保基金 / 头部 VC"},{"date":"2024","round":"A轮","amount":"近5亿元","inv":"社保基金中关村自主创新专项基金、启明创投、洪泰基金联合领投，联想创投、小米、软通高科等跟投，国开科创、上海人工智能产业投资基金、徐汇科创投等国资基金及顺为资本、达晨财智、德同资本、尚势资本、申万宏源等"},{"date":"2023-05","round":"种子轮","inv":"红杉中国、北极光创投、金沙江创投、SEE Fund无限基金、徐汇资本"},{"date":"2023","round":"天使轮","inv":"百度、腾讯投资、红杉中国、智谱AI、歌尔股份、真格基金、启明创投、经纬创投、南山资本、绿洲资本Vitalbridge、七熹投资、光源资本、星连资本、惠隆资本"}],"investorsStructured":[{"name":"杭州高新金投","role":"follow","round":"C轮","date":"2026-10","kind":"gov","note":"杭州高新区国资平台"},{"name":"社保中关村基金","role":"follow","round":"C轮","date":"2026-10","kind":"gov","note":"由君联资本管理"},{"name":"珠海科技产业集团","role":"follow","round":"C轮","date":"2026-10","kind":"gov"},{"name":"厦门国兴投资","role":"follow","round":"C轮","date":"2026-10","kind":"gov"},{"name":"徐汇资本","role":"follow","round":"C轮","date":"2026-10","kind":"gov","note":"上海徐汇区国资背景"},{"name":"孚腾资本","role":"follow","round":"C轮","date":"2026-10","kind":"gov","note":"上海国投旗下"},{"name":"中保投资","role":"follow","round":"C轮","date":"2026-10","kind":"pe"},{"name":"国开科创","role":"follow","round":"C轮","date":"2026-10","kind":"gov","note":"国家开发银行旗下科创投资平台"},{"name":"Dabanc Holding","role":"follow","round":"C轮","date":"2026-10","kind":"other"},{"name":"联想","role":"strategic","round":"C轮","date":"2026-10","kind":"cvc"},{"name":"九坤创投","role":"follow","round":"C轮","date":"2026-10","kind":"vc"},{"name":"同歌创投","role":"follow","round":"C轮","date":"2026-10","kind":"vc"},{"name":"腾讯","role":"strategic","round":"C轮","date":"2026-10","kind":"cvc"},{"name":"百度","role":"strategic","round":"C轮","date":"2026-10","kind":"cvc"},{"name":"砺思资本","role":"follow","round":"C轮","date":"2026-10","kind":"vc"},{"name":"启明创投","role":"lead","round":"A轮","date":"2024-08","kind":"vc","note":"多轮跟投，亦参与 C 轮"},{"name":"惠远资本","role":"lead","round":"战略融资","date":"2025-05","kind":"pe"},{"name":"杭州高新金投集团","role":"lead","round":"战略融资","date":"2025-05","kind":"gov"},{"name":"洪泰基金","role":"lead","round":"A轮","date":"2024-08","kind":"vc"},{"name":"社保基金中关村自主创新专项基金","role":"lead","round":"A轮","date":"2024-08","kind":"gov"},{"name":"红杉中国","role":"lead","round":"种子轮","date":"2023-05","kind":"vc"},{"name":"小米","role":"strategic","round":"A轮","date":"2024-08","kind":"cvc"},{"name":"北极光创投","role":"follow","round":"种子轮","date":"2023-05","kind":"vc"},{"name":"君联资本","role":"follow","round":"A+轮","date":"2025-11","kind":"vc"},{"name":"智谱AI","role":"follow","round":"天使轮","date":"2023-09","kind":"vc"},{"name":"百度","role":"follow","round":"天使轮","date":"2023-09","kind":"cvc"},{"name":"联想创投","role":"follow","round":"A轮","date":"2024-08","kind":"cvc"},{"name":"腾讯投资","role":"follow","round":"天使轮","date":"2023-09","kind":"cvc"},{"name":"金沙江创投","role":"follow","round":"种子轮","date":"2023-05","kind":"vc"}]}'::jsonb, now())
