INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at)
VALUES ('毛草乐园', NULL, 'ai', 'ai-app', false, '种子轮', NULL, NULL, NULL, '2026-10', '{"name":"毛草乐园","industry":"ai","seg":"ai-app","listed":false,"desc":"AI 原生 IP 人格硬件企业，由泡泡玛特前设计师王丽丽联合前大疆业务负责人创立，将大模型交互能力与毛绒玩偶载体深度融合，瞄准 20-35 岁愿为情绪价值付费的年轻群体。公司打造兔子「咬咬」、小草「潦草草」两大核心 IP，每个角色具备完整人设与世界观，产品内置语音交互、闹钟、音响、香薰等家居功能，并通过触摸触发多感官反馈。","round":"种子轮","lastFunding":"2026-10","latestFunding":"2026 年 10 月完成红杉中国种子轮融资，并已启动新一轮融资；金额未披露。","latestTech":"AI 原生 IP 人格硬件：将大模型对话能力与 IP 人设深度绑定，依赖角色设定、知识内容与长期记忆能力，使互动脱离固定问答；支持触摸 + 语音多模态反馈，自研虚拟交互逻辑实现「AI 能力服务于 IP 人格」而非功能外挂。","tech":[{"date":"2026-10","title":"两款核心 IP 产品展会首发售罄","kind":"产品","desc":"兔子「咬咬」、小草「潦草草」在展会亮相后新品首发很快售罄，验证 IP + 硬件组合的市场吸引力。"}],"funding":[{"date":"2026-10","round":"种子轮","amount":"未披露","inv":"红杉中国","investors":"红杉中国"}],"investorsStructured":[{"name":"红杉中国","role":"lead","round":"种子轮","date":"2026-10","kind":"vc","note":"种子轮独家投资方"}],"executives":[{"name":"王丽丽","title":"联合创始人","role":"management","bio":"泡泡玛特前设计师，具备成熟 IP 内容打造能力。"}],"note":"创始团队为「潮玩 IP 内容 + 消费硬件工程」跨界组合，另一位联合创始人为前大疆业务负责人。产品准则：「剥离 IP 光环，硬件本身依然值得购买；去掉智能功能，用户依旧愿意为这个玩偶买单」。"}'::jsonb, now())
