INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at)
VALUES ('跃瓦创新', NULL, 'ai', 'ai-app', false, 'Pre-A 轮', NULL, NULL, NULL, '2026-10', '{"name":"跃瓦创新","industry":"ai","seg":"ai-app","listed":false,"desc":"消费级具身智能多足机器人企业，2024 年 5 月成立，主打桌面级四足 AI 机器人 Cocowa，并延伸至家庭场景 AI 摄影台灯 Cocolamp。公司采用软硬件协同研发思路：硬件端持有多足机器人腿部折叠展开、云台折叠收纳等结构专利，解决小型消费多足机器人收纳不便、体积过大的痛点；软件端自研适配具身智能的底层协议，围绕机器人肢体动作、交互反馈完成定制化适配，而非直接套用通用大模型接口。","round":"Pre-A 轮","lastFunding":"2026-10","latestFunding":"2026 年 10 月完成 Pre-A 轮融资，由元璟资本参与投资；金额未披露。","latestTech":"自研具身智能底层协议，拥有运动协调控制、状态机指令、视觉接入等多项软件著作权；硬件侧持有多足机器人腿部折叠展开、云台折叠收纳结构专利。研发重心在拟人化情绪表达与娱乐交互体验，让机器人肢体动作可随对话实时反应，强化产品「生命感」。","tech":[{"date":"2024-06","title":"获红杉中国早期投资","kind":"融资","desc":"成立仅一个月即获红杉中国早期投资。"},{"date":"2026-06","title":"美团、梅花创投成为新增投资方","kind":"融资","desc":"工商股权信息变更，后续元璟资本、新势能等机构相继参与。"}],"funding":[{"date":"2026-10","round":"Pre-A 轮","amount":"未披露","inv":"元璟资本","investors":"元璟资本"},{"date":"2026-06","round":"早期轮次","amount":"未披露","inv":"美团 / 梅花创投 / 新势能","investors":"美团 · 梅花创投 · 新势能"},{"date":"2026-03","round":"早期轮次","amount":"未披露","inv":"XVC","investors":"XVC"},{"date":"2024-06","round":"天使轮","amount":"未披露","inv":"红杉中国","investors":"红杉中国"}],"investorsStructured":[{"name":"元璟资本","role":"lead","round":"Pre-A 轮","date":"2026-10","kind":"vc"},{"name":"美团","role":"strategic","round":"早期轮次","date":"2026-06","kind":"cvc","note":"美团产业资本，2026 年 6 月工商股权变更时新增"},{"name":"梅花创投","role":"follow","round":"早期轮次","date":"2026-06","kind":"vc"},{"name":"新势能","role":"follow","round":"早期轮次","date":"2026-06","kind":"vc"},{"name":"XVC","role":"follow","round":"早期轮次","date":"2026-03","kind":"vc"},{"name":"红杉中国","role":"lead","round":"天使轮","date":"2024-06","kind":"vc","note":"成立仅一个月即参与的早期投资"}],"note":"对外最早曝光产品为桌面级四足 AI 机器人 Cocowa；近期有报道根据其海外账号状态推测产品方向或调整为面向家庭场景的 AI 摄影台灯 Cocolamp，该变动尚未获官方证实。"}'::jsonb, now())
