VALUES ('NEXFORM新元体', NULL, 'ai', 'ai-app', false, '种子轮', NULL, NULL, NULL, '2026-10', '{"name":"NEXFORM新元体","industry":"ai","seg":"ai-app","listed":false,"desc":"Physical AGI 企业，围绕「通用硬件平台 + 开发者生态 + 物理智能体」展开布局，以 AI for Physical AI 为研发范式，通过 AI Agentic 开展 Auto Research，以 Physical RSI（递归自我改进）为技术路线，推动机器人实现自我进化。属浙大系创业公司。","round":"种子轮","lastFunding":"2026-10","latestFunding":"2026 年 10 月完成数千万元种子轮融资，投资方包括戈壁创投、浙大友创等。","latestTech":"Physical AGI 技术栈：以 AI Agentic 驱动 Auto Research 实现自动化研究迭代，以 Physical RSI（递归自我改进）为路径推动机器人自我进化；布局通用硬件平台与开发者生态，构建「物理智能体」闭环。","tech":[{"date":"2026-10","title":"完成数千万元种子轮融资","kind":"融资","desc":"投资方为戈壁创投、浙大友创等。"}],"funding":[{"date":"2026-10","round":"种子轮","amount":"数千万元","inv":"戈壁创投 / 浙大友创","investors":"戈壁创投 · 浙大友创"}],"investorsStructured":[{"name":"戈壁创投","role":"lead","round":"种子轮","date":"2026-10","kind":"vc"},{"name":"浙大友创","role":"follow","round":"种子轮","date":"2026-10","kind":"vc","note":"浙大系校友创投基金"}],"note":"浙大系创业企业，2026-10-14 正式对外宣布种子轮融资。"}'::jsonb, now())
