VALUES ('天序智能', NULL, 'ai', 'ai-app', false, 'Pre-A+ 轮', NULL, NULL, NULL, '2026-10', '{"name":"天序智能","industry":"ai","seg":"ai-app","listed":false,"desc":"高分辨率气象大模型研发与行业落地企业，2024 年 10 月成立于浙江嘉兴桐乡，专注能源气象垂直赛道。创始人刘栗为中国科学院大学气象学博士，本硕博深耕气象专业，在气象、人工智能与能源交叉领域深耕近 10 年。公司自研「洛伦兹框架」能源气象大模型，并启动「凝空星座」自主卫星观测网络，是国内极少数完成「大模型上星」的创业公司，构建「太空观测—气象大模型—能源垂直世界模型—仿真行业底座交付」全链条。","round":"Pre-A+ 轮","lastFunding":"2026-10","latestFunding":"2026 年 10 月完成数千万元 Pre-A+ 轮融资，由厚雪资本独家投资，翊荣资本担任长期独家财务顾问。资金用于「凝空星座」建设、CMA-WSP-AI 及垂类世界模型迭代、团队扩张、重点客户拓展与海外业务预研。","latestTech":"自研「洛伦兹框架」能源气象大模型（参数规模 10B 以内垂直领域模型），以 Transformer 为底层框架，针对能源气象上下游空间关联与时间漂移现象改造传统注意力机制，聚焦风速和辐照度预报。2025 年 10 月联合发布国内首个能源气象大模型 CMA-WSP-AI，1km 高精度风速预测指标优于 EC-HRES，极端天气竞赛 TS 评分提升 39.6% 至 351%；2026 年 7 月气象大模型搭载卫星入轨验证，规划部署 18 颗卫星构建全球 1km/1h 风、光、温压湿观测网络。","tech":[{"date":"2025-10","title":"联合发布国内首个能源气象大模型 CMA-WSP-AI","kind":"模型","desc":"1km 高精度风速预测指标优于 EC-HRES，极端天气竞赛 TS 评分提升 39.6% 至 351%。"},{"date":"2026-07","title":"气象大模型搭载卫星入轨验证","kind":"里程碑","desc":"2026-07-24 完成入轨并实现每日验证，规划部署 18 颗卫星，建成全球 1km/1h 风光温压湿观测网络。"}],"funding":[{"date":"2026-10","round":"Pre-A+ 轮","amount":"数千万元","inv":"厚雪资本（独家）","investors":"厚雪资本（独家）"}],"investorsStructured":[{"name":"厚雪资本","role":"lead","round":"Pre-A+ 轮","date":"2026-10","kind":"vc","note":"独家投资"}],"executives":[{"name":"刘栗","title":"创始人","role":"management","bio":"中国科学院大学气象学博士，本硕博深耕气象专业，在气象、人工智能与能源交叉领域深耕近 10 年。"}],"note":"核心团队由气象学博士、AI 专家和能源行业资深人士联合创立，成员来自中国科学院、复旦大学、国家气象局等机构，硕士及以上人员占比超 80%。客户覆盖发电侧头部央企、国家电网与南方电网；已跑通数据售卖、SaaS 平台订阅及私有化部署三层商业模式。低空气象服务分辨率达 10 米级。"}'::jsonb, now())
