INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at)
VALUES ('荆华密算', NULL, 'ai', 'maas', false, 'Pre-A 轮', NULL, NULL, NULL, '2026-10', '{"name":"荆华密算","industry":"ai","seg":"maas","listed":false,"desc":"AI 密态计算技术服务商，2024 年成立于北京海淀，孵化于清华大学计算机系，专注提升人工智能密态计算的性能与训练效率。公司独创「线性与非线性计算分离」架构，将密态计算性能损耗从千倍量级压缩至可商用水平并实现 100% 精度还原。已发布「全链路密态计算平台」，覆盖算力层、模型层、应用层到数据保证层，全面兼容昇腾、海光等国产算力，摆脱对海外 GPU-TEE 依赖。","round":"Pre-A 轮","lastFunding":"2026-10","latestFunding":"2026 年 10 月完成近亿元 Pre-A 轮融资，由中关村科学城、北创投联合领投，华仓资本、极致投资联合投资，老股东英诺科创基金、盛景嘉成创投持续加注，逐浪资本担任首席财务顾问。半年内已连续完成三轮融资。资金投向国产算力深度适配、底层密态计算技术迭代及密态专用芯片研发。","latestTech":"「线性与非线性计算分离」架构：95% 线性算子交给 GPU 密态计算，5% 非线性算子交给 CPU 可信环境或自研密态芯片，损耗降至可商用水平；基于「一次一密」的 OTP（一次性密码本）架构，在 GPU 内部完全以密文进行计算。全链路密态计算平台涵盖明文传输、隐私模式、GPU 机密计算及 GPU-OTP 模式等多重防护档位。可信 Token 产品单周消耗量突破 100 亿。","tech":[{"date":"2026-10","title":"「全链路密态计算平台」在北京发布","kind":"产品","desc":"提供从算力层、模型层、应用层到数据保证层的全方位服务，支持按数据敏感度自主选配防护档位。"},{"date":"2026-10","title":"联合中国人民保险推出全球首个 AI 数据保险","kind":"合作","desc":"赔付上限达 200 万元。"}],"funding":[{"date":"2026-10","round":"Pre-A 轮","amount":"近亿元","inv":"领投：中关村科学城 / 北创投；联合投资：华仓资本 / 极致投资；老股东加注：英诺科创基金 / 盛景嘉成创投","investors":"中关村科学城（领投）· 北创投（领投）· 华仓资本 · 极致投资 · 英诺科创基金 · 盛景嘉成创投"}],"investorsStructured":[{"name":"中关村科学城","role":"lead","round":"Pre-A 轮","date":"2026-10","kind":"gov","note":"联合领投"},{"name":"北创投","role":"lead","round":"Pre-A 轮","date":"2026-10","kind":"gov","note":"北京科技创新投资管理有限公司，联合领投"},{"name":"华仓资本","role":"follow","round":"Pre-A 轮","date":"2026-10","kind":"vc"},{"name":"极致投资","role":"follow","round":"Pre-A 轮","date":"2026-10","kind":"vc"},{"name":"英诺科创基金","role":"follow","round":"Pre-A 轮","date":"2026-10","kind":"vc","note":"老股东持续加注"},{"name":"盛景嘉成创投","role":"follow","round":"Pre-A 轮","date":"2026-10","kind":"vc","note":"老股东持续加注"}],"executives":[{"name":"林修醇","title":"创始人、CEO","role":"management","bio":"本科期间获国家奖学金并以第一作者发表顶刊，后于北京大学光华管理学院攻读商科博士，因团队取得重大技术突破且看好 AI 数据安全需求而休学创业。"},{"name":"任炬","title":"首席科学家","role":"management","bio":"长江学者，清华大学计算机系人机交互与媒体集成研究所所长。"}],"note":"相关方案曾随跨国企业落地 17 个国家和地区，服务近 1 亿用户。已与多家算力云厂商签订战略合作框架并完成部分产品接入。"}'::jsonb, now())
